SELECT id, user_id, token_hash, expires_at, revoked, revoked_at, created_at, updated_at
FROM auth_refresh_token
WHERE id = #{id}

SELECT id, user_id, token_hash, expires_at, revoked, revoked_at, created_at, updated_at
FROM auth_refresh_token
WHERE token_hash = #{tokenHash} AND revoked = false AND expires_at > #{now}
